"""Writes docs/REPORT_FACTS.md from experiments/**/metrics.json and the code itself.

    .venv\\Scripts\\python.exe scripts/make_report_facts.py

Every number in the documents must agree with that file.
"""
import json
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
os.environ.setdefault("PARKSURE_DB", "sqlite://")
EXP = ROOT / "experiments"


def J(name):
    return json.loads((EXP / name / "metrics.json").read_text(encoding="utf-8"))


def loc(pattern_dirs, exts):
    n = files = 0
    for d in pattern_dirs:
        for p in Path(d).rglob("*"):
            if p.is_file() and p.suffix in exts and "node_modules" not in p.parts and "dist" not in p.parts and ".venv" not in p.parts and "docs" not in p.relative_to(d).parts and p.name not in ("verify_docs.py",):
                n += sum(1 for _ in open(p, encoding="utf-8", errors="ignore"))
                files += 1
    return files, n


SHOTS = {
    "01_landing_dark": "Landing page, dark theme (three.js hero, live location counters)",
    "02_landing_how_it_works": "Landing page, 'how it works' storytelling section",
    "03_landing_features": "Landing page, feature section",
    "04_landing_light": "Landing page, light theme",
    "05_login": "Log in / create account with demo-login chips",
    "06_find_parking": "Find parking: availability cards for the default window (6 locations)",
    "07_search_full_lot": "Search result where the one-bay Kiosk Bay is Full for the window",
    "08_reserve_dialog": "Reserve dialog with the fee estimate (hours x rate x trust multiplier)",
    "09_reservation_confirmed": "Reservation confirmed state of the dialog",
    "10_my_bookings": "My bookings table with Check in / Cancel / Confirm demo payment actions",
    "11_check_in_toast": "Check-in success toast",
    "12_check_out_toast": "On-time check-out toast and the completed booking row",
    "13_trust_score": "Trust Score page: score, multiplier, streak, event timeline",
    "14_bookings_before_arrival": "Second driver's booking before arrival (one-bay lot occupied)",
    "15_moved_to_alternate": "Arrival at the full lot: moved to the nearest alternate (haversine 0.1 km), original booking marked Unable to park",
    "16_bookings_after_move": "Bookings after the move: replacement booking marked 'Alternate for #...'",
    "17_admin_overview": "Admin overview: users, locations, reservations, revenue, unable to park, declined",
    "18_admin_locations": "Admin locations table with add / edit / delete / reset buffers",
    "19_admin_insights": "Strategy insights: four buffer policies replayed on stored history (chart)",
    "20_admin_bookings": "Admin all-bookings table with search and status filter",
    "21_admin_users": "Admin users table with trust and credit",
    "22_admin_insights_table": "Strategy insights per-location actual-versus-simulated table",
    "23_mobile_find_parking": "Find parking at 390 px phone width",
    "24_api_docs": "FastAPI OpenAPI documentation page (/docs) listing the 22 routes",
}


def main():
    pop, bad = J("buffer_population"), J("buffer_badshare")
    abl, td, seed = J("trust_ablation"), J("trust_dynamics"), J("seeded_history")
    par, ut = J("engine_parity"), J("unit_tests")
    lat, race, sec = J("api_latency"), J("concurrency_race"), J("security_probes")
    from app.main import app
    routes = [(sorted(r.methods - {"HEAD", "OPTIONS"})[0], r.path) for r in app.routes if hasattr(r, "methods") and r.path.startswith("/api")]
    bf, bl = loc([ROOT / "app"], {".py"})
    sf, sl = loc([ROOT / "scripts"], {".py"})
    tf, tl = loc([ROOT / "tests"], {".py"})
    ff, fl = loc([ROOT / "frontend" / "src"], {".js", ".jsx", ".css"})
    L = []
    w = L.append
    w("# REPORT_FACTS - Online Vehicle Parking Reservation System (ParkSure), batch CSE-C-C3\n")
    w("Single source for every number in the project documents. Generated by `scripts/make_report_facts.py` from `experiments/**/metrics.json`; measured on 2026-10-26.\n")
    w("## 1. Identity\n")
    w("- Product ParkSure; project title **Online Vehicle Parking Reservation System**; batch C3 (CSE-C); ports backend 8403, frontend 5403.")
    w("- Students: Palle Yashaswini 23K91A05H9; Mohammed Muneeb Ahmed 24K95A0518; Kamasani Manisha 24K95A0513; Pothagani Nithyya Bhargava 23K91A05J6. Guide: V Pallavi.")
    w("- Domain: Web Development and Smart Urban Infrastructure. Keywords from the batch file.\n")
    w("## 2. Base papers (read both PDFs)\n")
    w("- **Base paper named in the batch documents (3, 5)**: M. Jemmali, L. K. B. Melhim, A. Ammar, T. R. Gadekallu, W. Boulila, \"Smart Parking for Medical Cities via Passenger-Aware Allocation and Fast Grouping-Permutation Heuristics,\" IEEE Open J. Comput. Soc., vol. 7, pp. 1106-1118, 2026, doi 10.1109/OJCS.2026.3693801. Content: passenger-count-based allocation across parking zones, six grouping-permutation algorithms, nine instance classes, 2,790 test cases, best algorithm GVb/GVF (best-solution 68.2 %), GVb matched or beat baseline MR on 1,547 of 2,790 instances (55.4 %), architecture with booking interface, IoT sensing and a central allocation engine. No web product, payment or reservation buffer.")
    w("- **Technical basis of the implemented rules (in `archived_base_papers/` and `8.ProjectCode/`)**: G. Cabri, M. Montangero, F. Muzzini, R. Wang, \"Reservation Based Smart Parking Management,\" arXiv:2605.17650 [cs.MA], May 2026. Content: reservation module with a buffer of non-reservable slots (dynamic: +1 when a vehicle leaves AFTER its reservation ends, up to a maximum, periodic reset), reward system with 0-5 stars (B benefits -> +1, W warnings -> -1, fee and suspension effects), one alternate area suggested, SUMO simulation with 80 spots in 8 areas, population 80-110, 25-50 % bad vehicles, 1 h overstay, 5 runs, compared static 0/1/3 buffers; qualitative result only (figures, no numeric table): any buffer beats none, dynamic gives the best trade-off.")
    w("- Report convention: the OJCS paper is the batch's registered base paper (reference [1]); the arXiv paper is the technical basis whose buffer/star rules ParkSure implements (reference [2]). Comparison sections must say plainly that datasets and settings differ.\n")
    w("## 3. Architecture and code facts\n")
    w("- Backend: Python 3.11+ (venv Python 3.14.7), FastAPI 0.141.1, SQLAlchemy 2.0.52, SQLite file `parksure.db`, APScheduler 3.11.3 (buffer reset job every 30 min), python-jose JWT HS256 (12 h), bcrypt 5.0.0 (cost 12), Stripe SDK 15.6.1 (test mode with offline demo fallback), pydantic 2.13.5, uvicorn 0.52.4.")
    w("- Frontend: React 19 + Vite 8, react-router 7, three.js hero, framer-motion, GSAP, Recharts, lucide icons; kit V3 'Depth Studio'; dev server 5403 proxies /api to 8403. Original vanilla pages in `static/` still served by FastAPI.")
    w(f"- Code size: backend `app/` {bf} files, {bl} lines; `scripts/` {sf} files, {sl} lines; `tests/` {tf} files, {tl} lines; frontend `src/` {ff} files (js/jsx/css), {fl} lines.")
    w("- Backend modules: `main.py` (routes, scheduler, static), `engine.py` (buffer, admission, haversine, trust, fees), `models.py` (5 tables), `auth.py`, `schemas.py`, `stripe_pay.py`, `config.py`, `database.py`, `seed.py`.")
    w("- Database tables (5): users (id, name, email unique, password_hash, role, trust_score, benefit_streak, warning_count, account_credit, suspended_until, created_at); parking_locations (id, name, address, latitude, longitude, capacity, buffer_size, price_per_hour, last_buffer_reset, created_at); reservations (id, user_id FK, location_id FK, start_time, end_time, status, fee, fee_multiplier, checked_in_at, checked_out_at, decline_reason, parent_id, created_at); payments (id, reservation_id FK unique, user_id FK, amount, currency, provider, stripe_session_id, stripe_payment_intent, status, created_at); trust_events (id, user_id FK, kind, detail, created_at). Reservation statuses: reserved, active, completed, cancelled, failed, declined. Payment statuses: pending, paid, refunded, failed.")
    w("- Core rules: admission `overlapping_bookings + buffer < capacity` (engine.forecast_free); buffer init 1, +1 on every ON-TIME checkout (<= end + 10 min) up to 5, reset to 1 every 24 h by the scheduler; arrival check `active_parked >= capacity` -> exactly one nearest alternate by haversine (R = 6371 km) with forecast space, auto-created as an active booking with parent_id, else status failed and fee credited; trust 0-5 start 3, 3 benefits -> +1, 2 warnings -> -1; fee multiplier {0:1.75,1:1.5,2:1.25,3:1.0,4:0.95,5:0.9}; minimum billed time 0.25 h; suspension when trust < 1.5 and a warning within 14 days (24 h cooldown, re-applied at each refused request); bookings limited to 30 days; account credit offsets fees.")
    w("- **Direction of the shipped dynamic buffer differs from arXiv:2605.17650** (code grows the buffer on on-time checkouts, the paper on late departures); the experiments below measure both (`dynamic_parksure` and `dynamic_paper`). The product code was not changed during the documentation run.")
    w("- Lockout difference: the engine's suspension re-triggers at every request while trust < 1.5 and the last warning is < 14 days old, so a suspended driver is locked out for at least 14 days after the last warning (paper: one subsequent session).\n")
    w(f"### API endpoints ({len(routes)} routes)\n")
    for m, p in routes:
        w(f"- {m} {p}")
    w("\nAuth: Bearer JWT; roles driver / admin (first account on an empty DB becomes admin). Errors `{detail}`; 409 full window, 403 suspended, 401 bad credentials, 422 validation.\n")
    w("## 4. Data (no ML dataset)\n")
    w("ParkSure has no machine-learning model and no external dataset. The only data are the demo seed (`app/seed.py`, `random.Random(42)`), generated by the product itself and therefore SYNTHETIC:")
    sc = seed["status_counts"]
    w(f"- Seeded database: {seed['users']} users (1 admin, 8 drivers; drivers 3 and 6 have overstay history), {seed['locations']} locations (Central Station Garage 20 bays $4.00/h, Market Street Lot 12 / $3.00, Riverside Parking 15 / $2.50, Airport Express Park 25 / $5.00, Old Town Deck 8 / $2.00; Bengaluru coordinates), {seed['reservations']} reservations ({sc['completed']} completed, {sc['failed']} failed = unable to park, {sc['declined']} declined, {sc['reserved']} reserved), {seed['payments']} payments; 60 days of history plus 8 Friday-evening over-subscription peaks at Old Town Deck. Licence: own code. Split: none (no model).")
    w("- Stripe is in test mode / demo fallback; no real payments were taken.\n")
    w("## 5. Test results\n")
    w(f"- pytest: **{ut['passed']} passed, {ut['failed']} failed** ({ut['summary_line']}); files: test_engine.py {ut['files']['tests/test_engine.py']} tests, test_api.py {ut['files']['tests/test_api.py']}, test_sim_parity.py {ut['files']['tests/test_sim_parity.py']}.")
    w("- `scripts/smoke_test.py`: 27 checks PASS + 1 optional frontend-proxy check (skipped when the dev server is down) on a throw-away DB.")
    w(f"- Engine parity (simulator vs real engine): {par['total_cases']} decisions, **{par['total_mismatches']} mismatches** (admission {par['admission']['cases']}, trust {par['trust']['cases']}, suspension {par['suspension']['cases']}).\n")
    w("## 6. API latency (measured on 127.0.0.1, single uvicorn process, SQLite file, 200 sequential requests per endpoint)\n")
    m = lat["machine"]
    w(f"Machine: {m['platform']}, Python {m['python']}, {m['processor']}; measured {lat['measured_at']}. Cost of `localhost` (IPv6 fallback) avoided by using 127.0.0.1.\n")
    w("| Endpoint | mean ms | p50 | p95 | p99 | max |")
    w("|---|---|---|---|---|---|")
    for k, v in lat["endpoints"].items():
        w(f"| {k} | {v['mean_ms']} | {v['p50_ms']} | {v['p95_ms']} | {v['p99_ms']} | {v['max_ms']} |")
    w("\nNotes: login is slow by design (bcrypt cost 12). `GET /api/reservations` and `GET /api/admin/bookings` are slow because `_res()` issues 2 queries per row (N+1) over ~400 stored rows. Throughput row = 8 threads x 60 requests of /api/search.\n")
    mb = J("engine_microbench")
    w("### 6b. Engine micro-benchmark (in-process, no HTTP; " + mb["database"] + ")\n")
    for k, v in mb.items():
        if isinstance(v, dict):
            w(f"- {k}: mean {v['mean_ms']} ms, p95 {v['p95_ms']} ms ({v['n']} calls)")
    w("\nThe admission decision itself is sub-millisecond; the base paper (OJCS) also reports sub-millisecond execution for its allocation heuristics, but they solve a different problem (zone load balancing), so the numbers are not comparable. `nearest_alternate` scans every other location with one query each (about 0.4 ms per location).\n")
    w("## 7. Over-booking race (concurrency)\n")
    w(f"- {race['trials']} trials x {race['simultaneous_requests_per_trial']} simultaneous reservation requests for a window with exactly {race['bookable_bays_per_trial']} bookable bay: **{race['trials_with_overbooking']} of {race['trials']} trials accepted more than one** (max {race['max_accepted_in_a_trial']}). Cause: admission check and insert are not atomic (no lock / transaction isolation on the count). Objective 'prevents double bookings' is therefore met sequentially but not under simultaneous requests.\n")
    w("## 8. Security probes (own system, throw-away DB)\n")
    for k, v in sec.items():
        w(f"- {k}: {json.dumps(v)}")
    w("\nMeaning: unauthenticated `GET /api/payments/demo-confirm` marks any reservation paid (demo-mode endpoint left enabled); booking windows in the past are accepted; check-in works 25 days early; a token forged with the shipped default JWT secret is accepted (secret must be set in production); no login rate limit; injection payloads rejected with 422 (parameterised ORM + pydantic); cross-user cancel blocked (404); markup in names stored verbatim (React escapes on render).\n")
    w("## 9. Buffer-policy experiment (simulator `scripts/parking_sim.py`, NOT SUMO)\n")
    w("Scenario re-created from arXiv:2605.17650: 8 areas x 10 bays (80), each vehicle 10 parks of 1-3 h, bad vehicles overstay 1 h, two 8-16 h outside stops, 30 seeds per cell (paper: 5 runs), ParkSure rules incl. Trust Score. Assumptions the paper does not give (arrival process, lead time 15-60 min, gaps 15-60 min, uniform area choice, first request U[0,2] h, check-in on time) are listed in `SIM_ASSUMPTIONS` and were fixed before the runs. Strategies: static_0/1/3, dynamic_parksure (as shipped), dynamic_paper (+1 on late departure). 'No reservation' = refused by admission; 'suspended' = refused by Trust lockout; 'No park' = admitted but no bay and no alternate; 'alt overflow' = moved to an alternate that was physically full (shipped code does not re-check).\n")
    names = {"static_0": "static 0", "static_1": "static 1", "static_3": "static 3", "dynamic_parksure": "dynamic (ParkSure)", "dynamic_paper": "dynamic (paper rule)"}

    def table(title, group, label):
        w(f"### {title}\n")
        w(f"| {label} | policy | requests | no reservation | suspended | no park | moved to alt | alt overflow | success rate | utilisation |")
        w("|---|---|---|---|---|---|---|---|---|---|")
        for k, strat in group.items():
            for s, r in strat.items():
                w(f"| {k} | {names[s]} | {r['requests']['mean']:.0f} | {r['no_reservation']['mean']:.1f} | {r['suspended']['mean']:.1f} | {r['no_park']['mean']:.2f} | {r['moved_to_alternate']['mean']:.1f} | {r['alt_overflow']['mean']:.2f} | {r['success_rate']['mean']:.3f} | {r['utilisation']['mean']:.3f} |")
        w("")

    table("9a. Varying population (25 % bad vehicles), means of 30 runs", pop["by_population"], "vehicles")
    table("9b. Varying share of bad vehicles (population random in 80-110), means of 30 runs", bad["by_bad_share"], "bad share")
    w("### 9c. Trust Score switched off (population random 80-110, means of 30 runs)\n")
    w("| bad share | trust | policy | no reservation | no park | alt overflow | success rate |")
    w("|---|---|---|---|---|---|---|")
    for b, v in abl["by_bad_share"].items():
        for t in ("trust_on", "trust_off"):
            for s, r in v[t].items():
                w(f"| {b} | {t} | {names[s]} | {r['no_reservation']['mean']:.1f} | {r['no_park']['mean']:.2f} | {r['alt_overflow']['mean']:.2f} | {r['success_rate']['mean']:.3f} |")
    w("\nFindings: (1) the shipped dynamic rule refuses the most reservations (buffer climbs to 5 because most checkouts are on time) and does not reduce No-park events meaningfully; (2) the paper-literal rule refuses fewer than the shipped one and similar to static 3, (3) 'No park' is rare in every policy (at most ~1.4 per ~1,000 requests) because the nearest-alternate step absorbs the overflow; (4) static 0 has the lowest refusals and highest utilisation but the most moves to alternates and alternate overflows; (5) the Trust lockout, not the buffer, is the largest source of refused requests once 25 % or more of the drivers are bad; (6) the paper's claim that the dynamic buffer gives the best trade-off is NOT reproduced for the shipped rule in this simulator, and the paper's own setting (SUMO, its parameters) was not available.\n")
    w("## 10. Trust dynamics (one driver, 100 daily sessions, 200 drivers per setting)\n")
    w("| overstay probability | mean final trust | std | mean fee multiplier | share ever suspended | median first suspension session |")
    w("|---|---|---|---|---|---|")
    for p, r in td["by_overstay_probability"].items():
        w(f"| {p} | {r['mean_final_trust']} | {r['std_final_trust']} | {r['mean_fee_multiplier']} | {r['share_ever_suspended']} | {r['median_first_suspension_session']} |")
    w("")
    w("## 11. Strategy Insights on the seeded history (deterministic replay, last 60 days, fresh seeded DB)\n")
    ins = seed["insights_60d"]
    w("| policy | unable to park | declined |")
    w("|---|---|---|")
    for k, v in ins["totals"].items():
        w(f"| {k} | {v['unable_to_park']} | {v['declined']} |")
    w("\nPer location (capacity, requests, actual unable/declined, dynamic unable/declined):")
    for p in ins["per_location"]:
        w(f"- {p['location']} cap {p['capacity']}, {p['requests']} requests, actual {p['actual']['unable_to_park']}/{p['actual']['declined']}, dynamic {p['simulated']['dynamic']['unable_to_park']}/{p['simulated']['dynamic']['declined']}, static0 {p['simulated']['fixed_0']['unable_to_park']}/{p['simulated']['fixed_0']['declined']}")
    w("\nThis replay runs on the synthetic seed, so it demonstrates the mechanism, not real-world performance. Its dynamic policy also grows the buffer on on-time checkouts and shows the same ordering as section 9.\n")
    w("## 12. Objective check (batch objectives 1-6)\n")
    w("1. Registration, authentication, 'vehicle profile': registration/login/JWT/roles done; **no vehicle profile (plate, model) exists** - gap.")
    w("2. Real-time slot availability: search returns forecast bookable bays per window (capacity - buffer - overlapping); no sensors, no physical occupancy feed.")
    w("3. Search, advance reservation, cancellation: done and tested.")
    w("4. Secure online payment and digital receipts: Stripe Checkout in test mode + demo fallback; payment status stored; **no downloadable receipt/PDF in the app** (a `ParkSure_Product_Documentation.pdf` is mentioned in README but is not in the tree) - partial; payment confirm endpoint weakness (section 8).")
    w("5. Admin dashboard: locations, users, bookings, revenue, unable-to-park, declined, Strategy Insights - done (occupancy is forecast, not live).")
    w("6. Evaluation of booking success rate, allocation efficiency, response time: measured here (sections 6, 9, 11); no real-user study.\n")
    w("## 13. Screenshot inventory (`docs/screenshots/`, 1440x900 PNG, captured 2026-10-26 by `scripts/capture_docs_screens.py` on a fresh seeded database; shows real app data)\n")
    for f in sorted(os.listdir(ROOT / "docs" / "screenshots")):
        w(f"- {f}: {SHOTS.get(f[:-4], '')}")
    w("")
    w("## 14. Not measured / honest gaps\n")
    w("- No SUMO run, no real parking-lot data, no user-acceptance study, no load test beyond 8 threads on one machine, no Stripe live-mode or webhook test with real keys, no accessibility audit tool run, no vehicle-profile or receipt feature, no hardware (barrier/sensor) integration.")
    w("- Hardware the numbers were measured on: 12th Gen Intel Core i5-12500 (6 cores, 12 threads), 15.7 GB RAM, Windows 11 Pro, Python 3.14.7 (venv), Node 24.19.0, Chrome (Playwright channel) for screenshots.")
    (ROOT / "docs" / "REPORT_FACTS.md").write_text("\n".join(L) + "\n", encoding="utf-8")
    print("wrote docs/REPORT_FACTS.md,", len(L), "lines")


if __name__ == "__main__":
    main()
